cd "C:/visual projects/sns-ref/data/map"; python - <<'E'
import json
for ed in('enhanced','classic'):
  d=json.load(open(f'fortress.{ed}.json',encoding='utf-8'))
  print(ed)
  for e in d['entities']:
    sc=e.get('script') or []
    if any(l and l[0]=='boss' for l in sc):
        print(e['tex'],e['x'],e['y'],json.dumps(sc,ensure_ascii=False))
