cd "C:/visual projects/sns-ref"; mkdir -p "C:/Users/3D6B~1/AppData/Local/Temp/claude/C--visual-projects-game/b7459343-774d-4e44-ba07-6ab779435a7e/scratchpad/sns/boss"; python - <<'E'
import json
names="dread cutqueen bull dragon alchemist torturetree pirate leviathan gasbag broken hippogriff lakewitch fauxjester mummy clay inquisitor monster monsterwitch ruinaxe ruinghost squiddragon nameless cloak deadking deadknight deadjudge butterfly".split()
en={m['name']:m for m in json.load(open('data/monsters_enhanced.json',encoding='utf-8'))}
cl={m['name']:m for m in json.load(open('data/monsters_classic.json',encoding='utf-8'))}
keys="title hp attack defense poise stamina poiseAttack runSpeed fireDef litDef bladedDef poisonDef holyDef darkDef salt ai type flags giant hover creature phaseThresh crazeThresh attackReach strongReach specialReach attackAnim strongAnim specialAnim boxWidth boxHeight blockReduce".split()
for n in names:
    m=en[n]; c=cl.get(n)
    print(n, m['title'][9] if 'title' in m else '', '|',{k:m[k] for k in keys[1:]})
    if c:
        diff={k:c[k] for k in keys[1:] if c.get(k)!=m.get(k)}
        print('   classic diff:',diff)
    print('   drops',m['drops'])
E

