			c.ethereal = true;
		}
	}
	if (monsterDef.ai == 13)
	{
		if (timeSinceChange <= 300f)
		{
			timeSinceChange += Game1.frameTime;
		}
		if (prevAttackType <= 0)
		{
			prevAttackType = grounded;
		}
		if (c.anim.animName == "takeoff" && c.anim.frame <= 1f)
		{
			timeSinceChange = 0f;
			prevAttackType = flying;
		}
		else if (c.anim.animName == "land" && c.anim.frame == 0f)
		{
			timeSinceChange = 0f;
			prevAttackType = grounded;
		}
	}
